create table public.reports (id uuid primary key, category_id text not null, ai_category_id text, ai_confidence double precision, description text not null, latitude double precision not null, longitude double precision not null, accuracy_m double precision, address text, captured_at timestamptz not null, location_precision text not null, location_is_mocked boolean, photo_path text not null unique, status text not null default 'submitted', city text, subregion text, district text, postal_code text, country_code text, payload_hash text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(category_id in ('pothole','sidewalk_damage','overflowing_bin','litter','damaged_city_equipment','other')), check(ai_category_id is null or ai_category_id in ('pothole','sidewalk_damage','overflowing_bin','litter','damaged_city_equipment','other')), check(ai_confidence is null or ai_confidence between 0 and 1), check(char_length(btrim(description)) between 10 and 1000 and description !~ E'[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]'), check(latitude between -90 and 90), check(longitude between -180 and 180), check(accuracy_m is null or accuracy_m>=0), check(location_precision in ('precise','approximate')), check(status in ('submitted','failed')), check(address is null or (char_length(address)<=1000 and address !~ E'[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]')), check(city is null or (char_length(city)<=200 and city !~ E'[\\x00-\\x1F\\x7F]')), check(subregion is null or (char_length(subregion)<=200 and subregion !~ E'[\\x00-\\x1F\\x7F]')), check(district is null or (char_length(district)<=200 and district !~ E'[\\x00-\\x1F\\x7F]')), check(postal_code is null or (char_length(postal_code)<=40 and postal_code !~ E'[\\x00-\\x1F\\x7F]')), check(country_code is null or country_code ~ '^[A-Z]{2}$'));
alter table public.reports enable row level security; revoke all on public.reports from anon,authenticated;
create function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now();return new;end $$;
create trigger reports_updated_at before update on public.reports for each row execute function public.set_updated_at();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('report-images','report-images',false,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
-- No object policies: only the server-side service role can access this private bucket.
